function mix(recs){var m={};recs.forEach(function(r){m[r.g]=(m[r.g]||0)+1;});return m;}
function diverge(a,b){
  var keys={};Object.keys(a).forEach(function(k){keys[k]=1;});Object.keys(b).forEach(function(k){keys[k]=1;});
  var d=0;Object.keys(keys).forEach(function(k){d+=Math.abs((a[k]||0)-(b[k]||0));});return d;}
